module PokemonGantzPort
  @registered = false
  @tilesets_injected = false
  @map_cache = {}

  # Load this mod's sparse TilesetsSparse.rxdata (1-based Array, index ==
  # tileset id) and splice every real entry into the live $data_tilesets.
  # NOTE: must never be named Tilesets.rxdata -- the mod manager's asset
  # installer blanket-copies this mod's Data/ over the game root's Data/,
  # which would clobber the real shared Tilesets.rxdata on disk.
  def self.inject_tilesets
    return if @tilesets_injected
    return unless defined?($data_tilesets) && $data_tilesets
    path = "#{PokemonGantzPortSettings::DATA_DIR}/TilesetsSparse.rxdata"
    return unless File.file?(path)
    arr = Marshal.load(File.binread(path))
    arr.each_with_index { |ts, i| $data_tilesets[i] = ts unless ts.nil? }
    @tilesets_injected = true
  end

  # Build (once, cached) the in-memory RPG::Map for a ported map id.
  def self.build_map(map_id)
    inject_tilesets
    return @map_cache[map_id] if @map_cache[map_id]
    path = "#{PokemonGantzPortSettings::DATA_DIR}/Map#{format('%05d', map_id)}.rxdata"
    @map_cache[map_id] = Marshal.load(File.binread(path))
  end

  def self.register
    return if @registered
    @registered = true
    s = PokemonGantzPortSettings
    s::PORTED_MAPS.each do |map_id, name|
      method_name = :"build_#{s::MOD_NAME.downcase}_map_#{map_id}"
      unless MultiverseHub.respond_to?(method_name)
        MultiverseHub.define_singleton_method(method_name) { PokemonGantzPort.build_map(map_id) }
      end
      MultiverseHub::GAUNTLET_MAP_BUILDERS[map_id] = method_name
      if map_id == s::START_MAP_ID
        MultiverseHubSettings::GAMES[s::GAME_KEY] = {
          name:              s::GAME_NAME,
          map_id:            map_id,
          map_name:          name,
          spawn:             s::START_SPAWN,
          seed_dynamic_warp: s::START_DYNAMIC_WARP,
        }
      else
        MultiverseHubSettings::EXTRA_GAUNTLET_MAP_NAMES[map_id] = name
      end
    end
    unless s::CONNECTIONS.empty?
      MultiverseHubSettings::EXTRA_MAP_CONNECTIONS.concat(s::CONNECTIONS)
    end
    MapFactoryHelper.clear if defined?(MapFactoryHelper)
  end
end

PokemonGantzPort.register
